bg=7
out=[[bg]*7 for _ in range(19)]
for start,color,pat in [(1,1,['101','101','111']),(7,4,['100','110','101']),(13,6,['111','010','111'])]:
    for r in range(5):
        for c in range(5): out[start+r][1+c]=color
    for r in range(3):
        for c in range(3):
            if pat[r][c]=='1': out[start+1+r][2+c]=bg
print('\n'.join(' '.join(map(str,row)) for row in out))
